import{_ as t,o as a,c as n,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy art and UI brief","description":"The current GDD owns the player experience, lesson route and nine activity rules.\\nLuis owns art assets, Miguel owns game UI implementation, Sherwin owns experience decisions, ","frontmatter":{"title":"Chainy art and UI brief","description":"The current GDD owns the player experience, lesson route and nine activity rules.\\nLuis owns art assets, Miguel owns game UI implementation, Sherwin owns experience decisions, ","source":"docs/design/design-brief.md","category":"Game & system design","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/design/design-brief.md","filePath":"content/docs/design/design-brief.md"}'),s={name:"content/docs/design/design-brief.md"};function i(o,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<div><h1 id="chainy-art-and-ui-brief">Chainy art and UI brief<a class="header-anchor" href="#chainy-art-and-ui-brief" aria-label="Link to this section">​</a></h1><p>The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">current GDD</a> owns the player experience, lesson route and nine activity rules. Luis owns art assets, Miguel owns game UI implementation, Sherwin owns experience decisions, Sean owns authored copy and Christian owns technical integration. <strong>Current work is documentation and necessary preparation only; game implementation requires final owner approval.</strong> The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/design/design-brief.html">previous brief</a> preserves superseded production requirements.</p><h2 id="visual-direction">Visual direction<a class="header-anchor" href="#visual-direction" aria-label="Link to this section">​</a></h2><p>Retain a fixed orthographic isometric camera, approximately 35–45 degrees top-down, and restrained stylized low-poly art. Use faceted silhouettes, readable routes, simple beveled planes, sparse surface detail and controlled lighting. The blue-haired Explorer in yellow, friendly white screen-faced robots and cyan record/block motifs remain the character identity. Sean guides Web3, Matthew guides Blockchain and Lee guides AI.</p><p>The supplied Tunic screenshots inform camera, lighting, material density and composition; do not copy their maps, characters, props, icons or HUD. Avoid voxel terrain, bright toy-diorama scenery, rounded animated-film rendering and close third-person framing.</p><p><img src="/Chainy-Docs/attachments/docs/media/gdd/reference-chainy-01.png" alt="Chainy character identity reference"></p><p>The <a href="/Chainy-Docs/attachments/docs/media/gdd/reference-chainy-02.png">second identity reference</a> supports the same characters. Old gameplay counts and screen layouts in these images are historical.</p><p><img src="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/isometric-exploration.png" alt="Isometric camera and composition target"></p><p>This is a concept reference for camera, scale, treatment and density, not an implemented level.</p><h2 id="screens-and-feedback">Screens and feedback<a class="header-anchor" href="#screens-and-feedback" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Screen or state</th><th>Required purpose and hierarchy</th></tr></thead><tbody><tr><td>Main menu and world selection</td><td>Play, three world cards, recorded count out of 13, collection/review status and sequential locks for Web3 → Blockchain → AI</td></tr><tr><td>Island HUD</td><td>Left joystick, contextual Interact, current objective, Encyclopedia, Quest and Pause; landmarks distinguish the current target</td></tr><tr><td>Tutorial and dialogue</td><td>Short instructions over the live world; only the overlay accepts input</td></tr><tr><td>Quest and lesson panel</td><td>Thirteen lessons in teaching order, one current step and location hint; term, meaning, example and Record action</td></tr><tr><td>Encyclopedia</td><td>Three categories with 13 entries each; alphabetical browsing is separate from teaching order and never awards progress</td></tr><tr><td>Minigame</td><td>Activity-specific controls and instructions, explanatory feedback, Retry and Pause/Exit; each of nine scenes must communicate its distinct rule</td></tr><tr><td>Required review</td><td>Thirteen questions, one per lesson, with four choices each; feedback and retries until all are correct; distinguish first-response score from corrected completion</td></tr><tr><td>Collection and world completion</td><td>Collection complete requires a review; only saved review completion unlocks the next world; AI completion offers revisits</td></tr><tr><td>Loading, saving and interruption</td><td>Clear pending state, input blocking, actionable Retry and safe return; show Recorded only after saving succeeds</td></tr></tbody></table><p>Use the <a href="/Chainy-Docs/content/docs/design/app-flow.html">player flow</a> and GDD for detailed interaction behavior. Retain readable wrapping, safe-area spacing, generous touch targets, text/icons alongside color and essential information that works with audio muted. Check these on the reference phone after development is authorized.</p><p>Dialogue stays layered over the live isometric world. Use the existing wide translucent bottom panel, speaker name, compact stacked response choices and Explorer/guide portraits. Disable world movement and interaction beneath it.</p><p><img src="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/dialogue-overlay.png" alt="Dialogue overlay placement target"></p><p>This image establishes layout direction; its example question is not the approved assessment content.</p><h2 id="island-and-activity-assets">Island and activity assets<a class="header-anchor" href="#island-and-activity-assets" aria-label="Link to this section">​</a></h2><p>Each island needs 13 recognizable lesson locations, including three ordered item/NPC/facility encounters. The GDD&#39;s <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html#7-complete-lesson-route">complete route</a> is the single inventory of lesson props and locations. Use compact layouts, clear landmarks and safe return positions.</p><table><thead><tr><th>World</th><th>Three activity scenes</th><th>Encounter props from the GDD</th></tr></thead><tbody><tr><td>Web3</td><td>Safe Address Handoff; Price Path; Message Inspector</td><td>Address card and dummy terminal; chart strip and history display; envelope and message kiosk</td></tr><tr><td>Blockchain</td><td>Archive Reconstruction; Condition Machine; Minimum Disclosure</td><td>Reference slip and archive workstation; rule card and condition console; sealed credential and proof exhibit</td></tr><tr><td>AI</td><td>Label Lab; Test the Helper; Fact Patch</td><td>Example tray and labeling desk; fresh-case pack and test station; reference sheet and text exhibit</td></tr></tbody></table><p>Reuse modular scenery, robot bases and presentation elements where they support each activity&#39;s distinct rules. Ordinary collectibles are teaching objects; prerequisite items appear as quest evidence rather than a managed inventory. AI scenes need visible simulation wording. Wallet balances, shops, lantern purchases, restoration systems, teacher services, exports and standalone Wordle/BlockMatch screens are outside current scope.</p><h2 id="production-handoff-after-approval">Production handoff after approval<a class="header-anchor" href="#production-handoff-after-approval" aria-label="Link to this section">​</a></h2><p>Review mockups and a representative camera/level sample before expanding asset production. Reuse suitable existing assets rather than assuming replacements are required. Luis supplies editable source and exports, intended scale, format, source/license, naming, import notes, preview and known gaps. Miguel implements reviewed screen states and provides UI artifacts; Sean supplies final text; Christian integrates behavior and checks import/device cost. Cross-role outputs pass through separate owner cards.</p><p>Polygon, texture, memory and performance budgets require measurements from the representative scene; no new numerical budgets are asserted here. Keep offline assets bundled and respect the target phone&#39;s memory and storage constraints. The November 21 pre-final remains fixed, but this inventory is not a delivery-time estimate.</p></div>',1)])])}const m=t(s,[["render",i]]);export{u as __pageData,m as default};
